function validate([n, requirements]) {
  if (!Number.isInteger(n) || n < 2 || n > 300) return 'n is a whole number from 2 to 300.';
  if (!Array.isArray(requirements) || requirements.length < 1 || requirements.length > n) return 'requirements needs 1 to n entries.';
  const ends = new Set();
  for (const r of requirements) {
    if (!Array.isArray(r) || r.length !== 2 || !r.every(Number.isInteger)) return 'Each requirement is a pair [end, cnt].';
    const [end, cnt] = r;
    if (end < 0 || end > n - 1) return 'Each end is between 0 and n - 1.';
    if (cnt < 0 || cnt > 400) return 'Each cnt is between 0 and 400.';
    if (ends.has(end)) return 'All ends must be different.';
    ends.add(end);
  }
  if (!ends.has(n - 1)) return 'One requirement must have end n - 1.';
  return null;
}

