function numberOfPermutations(n, requirements) {
  const MOD = 1_000_000_007;
  const need = new Array(n).fill(-1);
  let limit = 0;
  for (const [end, cnt] of requirements) {
    need[end] = cnt;
    limit = Math.max(limit, cnt);
  }

  let dp = new Array(limit + 1).fill(0);
  dp[0] = 1;
  for (let i = 0; i < n; i++) {
    const prefix = new Array(limit + 2).fill(0);
    for (let j = 0; j <= limit; j++) {
      prefix[j + 1] = (prefix[j] + dp[j]) % MOD;
    }
    const next = new Array(limit + 1).fill(0);
    for (let j = 0; j <= limit; j++) {
      const low = Math.max(0, j - i);
      next[j] = (prefix[j + 1] - prefix[low] + MOD) % MOD;
    }
    if (need[i] !== -1) {
      const kept = next[need[i]];
      next.fill(0);
      next[need[i]] = kept;
    }
    dp = next;
  }
  return dp[need[n - 1]];
}

