function numberOfPermutations(n, requirements) {
  const MOD = 1000000007;
  if (n <= 8) {
    // Small n: list every permutation and count the inversions of each required prefix directly.
    const perm = [], used = new Array(n).fill(false);
    let total = 0;
    const inversions = end => {
      let inv = 0;
      for (let a = 0; a <= end; a++) for (let b = a + 1; b <= end; b++) if (perm[a] > perm[b]) inv++;
      return inv;
    };
    const build = () => {
      if (perm.length === n) {
        if (requirements.every(([end, cnt]) => inversions(end) === cnt)) total++;
        return;
      }
      for (let v = 0; v < n; v++) {
        if (used[v]) continue;
        used[v] = true; perm.push(v);
        build();
        used[v] = false; perm.pop();
      }
    };
    build();
    return total % MOD;
  }
  // Larger n: element i has between 0 and i bigger elements before it, and these choices describe the permutation.
  // Count the choice sequences top-down, one position at a time, without prefix sums.
  const need = new Map(requirements.map(([end, cnt]) => [end, cnt]));
  const memo = new Map();
  const count = (i, inv) => {
    if (i === n) return 1;
    const key = i * 1000 + inv;
    if (memo.has(key)) return memo.get(key);
    let ways = 0;
    for (let c = 0; c <= i && inv + c <= 400; c++) {
      if (need.has(i) && need.get(i) !== inv + c) continue;
      ways = (ways + count(i + 1, inv + c)) % MOD;
    }
    memo.set(key, ways);
    return ways;
  };
  return count(0, 0);
}

