function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 101) : 2 + Math.floor(rand() * 6);
  // digits[i] = how many earlier elements are bigger than element i (0..i); their running sums are prefix inversion counts.
  const digits = new Array(n).fill(0);
  if (large) {
    const budget = Math.floor(rand() * 401);
    for (let placed = 0; placed < budget;) {
      const i = 1 + Math.floor(rand() * (n - 1));
      if (digits[i] < i) { digits[i]++; placed++; }
    }
  } else {
    for (let i = 0; i < n; i++) digits[i] = Math.floor(rand() * (i + 1));
  }
  const keep = [0, 0.03, 0.2, 0.6, 1][Math.floor(rand() * 5)];
  const requirements = [];
  let sum = 0;
  for (let end = 0; end < n; end++) {
    sum += digits[end];
    if (end === n - 1 || rand() < keep) requirements.push([end, sum]);
  }
  // Sometimes nudge one count so that no permutation may fit.
  if (rand() < 0.25) {
    const r = requirements[Math.floor(rand() * requirements.length)];
    r[1] = Math.min(400, Math.max(0, r[1] + Math.floor(rand() * 7) - 3));
  }
  for (let i = requirements.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [requirements[i], requirements[j]] = [requirements[j], requirements[i]];
  }
  return [n, requirements];
}
